import cx from 'classnames'
import { type FC, type ReactNode } from 'react'
import { CollapseIcon } from './collapse-icon'
import classes from './styles/dimension-card-header.module.css'

type DimensionCardHeaderProps = {
    children: ReactNode
    selectedCount: number
    isCollapsed: boolean
    onToggle: () => void
    isDisabled?: boolean
}

export const DimensionCardHeader: FC<DimensionCardHeaderProps> = ({
    children,
    selectedCount,
    isCollapsed,
    onToggle,
    isDisabled = false,
}) => {
    return (
        <button
            type="button"
            className={cx(classes.container, {
                [classes.collapsed]: isCollapsed,
            })}
            onClick={onToggle}
            aria-expanded={!isCollapsed}
            disabled={isDisabled}
            tabIndex={isDisabled ? -1 : 0}
            data-test="dimension-card-header"
        >
            <CollapseIcon isCollapsed={isCollapsed} />
            <div
                className={cx(classes.title, {
                    [classes.withSelection]: selectedCount > 0,
                })}
                data-test="dimension-card-header-title"
            >
                {children}
            </div>
            {selectedCount > 0 && (
                <div
                    className={classes.count}
                    data-test="dimension-card-header-count"
                >
                    {selectedCount}
                </div>
            )}
        </button>
    )
}
